IF t.input_versions->>'release_id' IS DISTINCT FROM r.release_id OR t.input_versions->>'release_manifest_sha256' IS DISTINCT FROM r.manifest_sha256 OR t.input_versions->>'cohort_sha256' IS DISTINCT FROM r.manifest->>'cohort_sha256' OR t.input_versions->>'membership_acceptance_sha256' IS DISTINCT FROM r.manifest->>'membership_acceptance_sha256' THEN RAISE EXCEPTION 'PRACTICAL_DELIVERY_TASK_INPUT_PIN';END IF;
IF t.payload->>'kind'='PRACTICAL_DELIVERY_VERIFY_V1' THEN
IF t.payload->>'target_family'='D02' THEN
FOR one IN WITH w AS MATERIALIZED(SELECT * FROM population_top3000_202608_202609_v1.working_daily_features_v1) SELECT w.session_date,count(*)expected_anchor_units,count(*)FILTER(WHERE i.source_count=1)source_single_rows,count(*)FILTER(WHERE i.source_count=0)source_missing_rows,count(*)FILTER(WHERE i.source_count>1)source_conflicting_rows,count(*)FILTER(WHERE i.source_count IS NULL)source_unknown_rows,count(*)FILTER(WHERE i.source_count=1 AND i.raw_close IS NOT NULL AND i.raw_volume IS NOT NULL AND i.dollar_volume IS NOT NULL)raw_fields_present_rows,count(*)FILTER(WHERE w.calculated_row_present)derived_rows,count(*)FILTER(WHERE i.unknown_actions>0)action_unknown_rows FROM w LEFT JOIN population_top3000_202608_202609_v1.daily_shared_input_v1 i ON i.run_id=w.run_id AND i.series_no=w.series_no AND i.session_date=w.session_date GROUP BY w.session_date ORDER BY w.session_date LOOP
v:=to_jsonb(one)||jsonb_build_object('unit','ANCHOR_COMPANY_SESSION_NOT_FULL_INSTRUMENT_DENOMINATOR','full_instrument_expected_units',NULL,'qualified_rows',0,'qualification','RETAINED_PRELIMINARY_SOURCE_VALUES_NOT_INDEPENDENT_ACCURACY','missing_is_zero',false,'family_accepted',false);
INSERT INTO population_top3000_202608_202609_v1.practical_delivery_coverage_v1 VALUES(r.release_id,'D02',one.session_date::text,v,encode(sha256(convert_to(v::text,'UTF8')),'hex')) ON CONFLICT DO NOTHING;GET DIAGNOSTICS n=ROW_COUNT;cnt:=cnt+n;IF NOT EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.practical_delivery_coverage_v1 c WHERE c.release_id=r.release_id AND c.family_id='D02' AND c.unit_key=one.session_date::text AND c.content=v AND c.record_sha256=encode(sha256(convert_to(v::text,'UTF8')),'hex')) THEN RAISE EXCEPTION 'PRACTICAL_DELIVERY_COVERAGE_REPLAY_CONFLICT';END IF;
END LOOP;
IF (SELECT count(*) FROM population_top3000_202608_202609_v1.practical_delivery_coverage_v1 WHERE release_id=r.release_id AND family_id='D02')<>42 OR (SELECT sum((content->>'expected_anchor_units')::bigint) FROM population_top3000_202608_202609_v1.practical_delivery_coverage_v1 WHERE release_id=r.release_id AND family_id='D02')<>126000 THEN RAISE EXCEPTION 'PRACTICAL_DELIVERY_D02_GRID_DEVIATION';END IF;
FOR one IN SELECT unit_key FROM population_top3000_202608_202609_v1.practical_delivery_coverage_v1 WHERE release_id=r.release_id AND family_id='D02' ORDER BY unit_key LOOP succ:=population_top3000_202608_202609_v1.pipeline_enqueue_v1('REF03','DELIVER','practical-delivery:'||r.release_id||':export:daily_features:'||one.unit_key,jsonb_build_object('kind','PRACTICAL_DELIVERY_EXPORT_V1','release_id',r.release_id,'dataset','daily_features','partition',one.unit_key),t.input_versions,tid);succs:=succs||jsonb_build_array(succ);END LOOP;
FOREACH ds IN ARRAY ARRAY['companies','breadth','readiness'] LOOP succ:=population_top3000_202608_202609_v1.pipeline_enqueue_v1('REF03','DELIVER','practical-delivery:'||r.release_id||':export:'||ds,jsonb_build_object('kind','PRACTICAL_DELIVERY_EXPORT_V1','release_id',r.release_id,'dataset',ds,'partition','*'),t.input_versions,tid);succs:=succs||jsonb_build_array(succ);END LOOP;
ELSIF t.payload->>'target_family'='S02' THEN
IF (SELECT count(*) FROM population_top3000_202608_202609_v1.archive_publication_member_v1 WHERE publication_id='1516e35a-b313-49fc-8b85-cf9128673be3' AND family_id='S02')<>135 OR (SELECT sum(b.row_count) FROM population_top3000_202608_202609_v1.archive_publication_member_v1 m JOIN population_top3000_202608_202609_v1.archive_delivery_batch_v1 b USING(publication_id,snapshot_id) WHERE m.publication_id='1516e35a-b313-49fc-8b85-cf9128673be3' AND m.family_id='S02')<>134931 THEN RAISE EXCEPTION 'PRACTICAL_DELIVERY_S02_SOURCE_PAGE_PIN';END IF;
FOR one IN SELECT * FROM(VALUES('2026-07-15',22373,false),('2026-07-31',22339,false),('2026-08-14',22480,true),('2026-08-31',22567,true),('2026-09-15',22593,true),('2026-09-30',22579,true))x(settlement_date,source_rows,target_window) LOOP
v:=to_jsonb(one)||jsonb_build_object('unit','SOURCE_ARCHIVE_SECURITY_SETTLEMENT_ROWS_NOT_COHORT_DENOMINATOR','archive_publication_id','1516e35a-b313-49fc-8b85-cf9128673be3','source_page_count',135,'retained_source_mechanics_review',6277,'retained_evidence_file_sha256','8cebb460c9c1aa64384812d4dbbdbfffbbd2807c920139a2015df77d252e5292','full_instrument_expected_units',NULL,'qualified_rows',0,'qualification','SOURCE_ARCHIVE_ONLY','original_wire_rehash_verified',false,'independent_source_accuracy_verified',false,'strict_point_in_time_qualified',false,'family_accepted',false,'missing_is_zero',false);
INSERT INTO population_top3000_202608_202609_v1.practical_delivery_coverage_v1 VALUES(r.release_id,'S02',one.settlement_date,v,encode(sha256(convert_to(v::text,'UTF8')),'hex')) ON CONFLICT DO NOTHING;GET DIAGNOSTICS n=ROW_COUNT;cnt:=cnt+n;IF NOT EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.practical_delivery_coverage_v1 c WHERE c.release_id=r.release_id AND c.family_id='S02' AND c.unit_key=one.settlement_date AND c.content=v AND c.record_sha256=encode(sha256(convert_to(v::text,'UTF8')),'hex')) THEN RAISE EXCEPTION 'PRACTICAL_DELIVERY_COVERAGE_REPLAY_CONFLICT';END IF;END LOOP;
ELSE RAISE EXCEPTION 'PRACTICAL_DELIVERY_TARGET_FAMILY';END IF;
SELECT encode(sha256(convert_to(jsonb_agg(jsonb_build_object('unit_key',unit_key,'hash',record_sha256) ORDER BY unit_key)::text,'UTF8')),'hex') INTO h FROM population_top3000_202608_202609_v1.practical_delivery_coverage_v1 WHERE release_id=r.release_id AND family_id=t.payload->>'target_family';
ELSE
ds:=t.payload->>'dataset';pk:=t.payload->>'partition';v:=population_top3000_202608_202609_v1.practical_delivery_read_v1(r.release_id,ds,pk,0,5000,false);n:=(v->>'row_count')::bigint;
IF n IS DISTINCT FROM (CASE ds WHEN 'daily_features' THEN 3000 WHEN 'companies' THEN 3000 WHEN 'breadth' THEN 42 WHEN 'readiness' THEN 24 ELSE -1 END) THEN RAISE EXCEPTION 'PRACTICAL_DELIVERY_EXPORT_COUNT';END IF;
h:=v->>'rows_sha256';INSERT INTO population_top3000_202608_202609_v1.practical_delivery_batch_v1 VALUES(r.release_id,ds,pk,n,h,v->>'source_projection') ON CONFLICT DO NOTHING;GET DIAGNOSTICS cnt=ROW_COUNT;
IF NOT EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.practical_delivery_batch_v1 WHERE release_id=r.release_id AND dataset=ds AND partition_key=pk AND rows_sha256=h AND row_count=n) THEN RAISE EXCEPTION 'PRACTICAL_DELIVERY_EXPORT_REPLAY_CONFLICT';END IF;
END IF;
IF (SELECT count(*) FROM population_top3000_202608_202609_v1.pipeline_task WHERE payload->>'release_id'=r.release_id AND payload->>'kind' IN('PRACTICAL_DELIVERY_VERIFY_V1','PRACTICAL_DELIVERY_EXPORT_V1'))>47 THEN RAISE EXCEPTION 'PRACTICAL_DELIVERY_TASK_LIMIT';END IF;
