SELECT jsonb_build_object('a',to_jsonb(a),'p',to_jsonb(p),'release',(SELECT to_jsonb(x)FROM population_top3000_202608_202609_v1.practical_delivery_release_v1 x WHERE release_id='practical-delivery-v1-76076'),'adapter',(SELECT to_jsonb(x)FROM population_top3000_202608_202609_v1.pipeline_adapter x WHERE family_id='REF03'AND stage='DELIVER'),'commit',(SELECT to_jsonb(x)FROM population_top3000_202608_202609_v1.pipeline_commit x WHERE commit_id='5a93d019-ea4d-4d35-9944-f36c59c99a29'),'tasks',(SELECT count(*)FROM population_top3000_202608_202609_v1.pipeline_task),'attempts',(SELECT count(*)FROM population_top3000_202608_202609_v1.pipeline_attempt),'commits',(SELECT count(*)FROM population_top3000_202608_202609_v1.pipeline_commit),'coverage',(SELECT count(*)FROM population_top3000_202608_202609_v1.practical_delivery_coverage_v1),'snapshot',(SELECT count(*)FROM population_top3000_202608_202609_v1.practical_delivery_snapshot_row_v1),'export',(SELECT count(*)FROM population_top3000_202608_202609_v1.practical_delivery_saved_export_v1))INTO afterstate FROM population_top3000_202608_202609_v1.acquisition_control a CROSS JOIN population_top3000_202608_202609_v1.pipeline_control p WHERE a.singleton AND p.singleton;
IF beforestate IS DISTINCT FROM afterstate THEN RAISE EXCEPTION 'RECEIPT79153_PROTECTED_STATE_CHANGED';END IF;
SELECT coalesce(sum(pg_total_relation_size(oid)),0)INTO afterbytes FROM pg_class WHERE relnamespace='population_top3000_202608_202609_v1'::regnamespace AND relkind IN('r','m');IF greatest(afterbytes-beforebytes,0)+greatest(coalesce((proof->>'paired_growth_bytes')::bigint,16777217),0)>16777216 THEN RAISE EXCEPTION 'RECEIPT79153_CUMULATIVE16MIB';END IF;
EXECUTE $finalclaim$DO $claim$ DECLARE c jsonb;ass jsonb;BEGIN
PERFORM population_top3000_202608_202609_v1.practical_delivery_guard_v1('practical-delivery-v1-76076');
SELECT details INTO STRICT c FROM population_top3000_202608_202609_v1.pipeline_event WHERE event_id=current_setting('receipt79153.claim_event_id')::bigint AND event='ENGINEERING_ASSIGNMENT_CLAIMED_V5';
SELECT details INTO STRICT ass FROM population_top3000_202608_202609_v1.pipeline_event WHERE event_id=79153 AND event='ENGINEERING_IMPLEMENTATION_ASSIGNMENT_V5';
IF c->>'assignment_event_id' IS DISTINCT FROM '79153' OR c->>'assignment_details_sha256' IS DISTINCT FROM '74b30a6fa4e1cc3d4e02b2f04a23dc98f6371923f656ac4f93fa86b160e38d7f' OR encode(sha256(convert_to(ass::text,'UTF8')),'hex') IS DISTINCT FROM c->>'assignment_details_sha256' OR c->>'executor' IS DISTINCT FROM 'automation:6adc2c96db348191bca7cf4eacfdac32' OR c->>'owner_id' IS DISTINCT FROM 'top3000-completion-20261024-root-5db48b32d103' OR c->>'owner_fence' IS DISTINCT FROM '3' OR c->>'stop_generation' IS DISTINCT FROM '1' OR c->>'scope_sha256' IS DISTINCT FROM '8e6ca1178f03822c34bb1b339818b34dcfdbf2a8642ef875e6e1af34dbf1bedd' OR ((c->>'expires_at')::timestamptz>clock_timestamp()) IS DISTINCT FROM true OR ((ass->>'not_after')::timestamptz>clock_timestamp()) IS DISTINCT FROM true OR EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_event WHERE event IN('ENGINEERING_ASSIGNMENT_COMPLETED_V5','ENGINEERING_ASSIGNMENT_EFFECTS_RECONCILED_RELEASE_V5') AND details->>'claim_event_id'=current_setting('receipt79153.claim_event_id')) THEN RAISE EXCEPTION 'RECEIPT79153_CURRENT_CLAIM';END IF;
END;$claim$;
$finalclaim$;END;$stage$;
SELECT event_id,event,details FROM population_top3000_202608_202609_v1.pipeline_event WHERE event IN('PRACTICAL_DELIVERY_HISTORICAL_LINEAGE_CORRECTION_V2','RECOVERY_DELEGATION_QUALIFIED_V1') ORDER BY event_id DESC LIMIT 2;COMMIT;
